import os, sys, json

def main() -> dict:
    # Check if wmill is importable
    try:
        import wmill
        wmill_available = True
        try:
            val = wmill.get_variable("u/gregoryivanonyxbadinas/enchanted_variable")
            gemini_key_len = len(val) if val else 0
            gemini_key_prefix = val[:8] if val else ""
        except Exception as e:
            gemini_key_len = -1
            gemini_key_prefix = str(e)[:60]
    except ImportError:
        wmill_available = False
        gemini_key_len = -1
        gemini_key_prefix = "wmill not importable"

    # Check env vars
    env_keys = {k: (v[:20] + "...") if len(v) > 20 else v 
                for k,v in os.environ.items() 
                if any(x in k.upper() for x in ["GEMINI","POSTGRES","SUPABASE","WM_","WINDMILL"])}

    return {
        "wmill_available": wmill_available,
        "gemini_key_len": gemini_key_len,
        "gemini_key_prefix": gemini_key_prefix,
        "python_version": sys.version[:20],
        "relevant_env_vars": env_keys,
    }
